sys_script_client.script:
function onSubmit() {

    var fields = [
        'annual_limit',
        'min_notice_days',
        'doc_after_days'
    ];

    var labels = [
        'Annual Limit',
        'Min Notice Days',
        'Doc After Days'
    ];

    for (var i = 0; i < fields.length; i++) {

        var value = g_form.getValue(fields[i]);

        if (value == '' || isNaN(value) || Number(value) <= 0) {

            g_form.showFieldMsg(
                fields[i],
                labels[i] + ' must be a positive number.',
                'error',
                false
            );

            return false;
        }
    }

    return true;
}
